window.AULAS["aula-07"] = {"id": "aula-07", "titulo": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "subtitulo": "Monoartrite, oligoartrite e poliartrite: do sintoma ao padrão", "pdf": "pdf/aula-07.pdf", "fontes": ["Aula 7 (slides do Prof. Dr. João Vítor Galo Esteves)", "Rocco, Semiologia Médica", "Bates, Propedêutica Médica"], "resumo": [{"titulo": "1. Como raciocinar em síndromes articulares (slides 2 a 4)", "pontos": [{"t": "Funil clínico (slide 2)", "sub": ["Reconhecer a queixa: dor referida, rigidez articular, aumento de volume.", "Descrever a síndrome: número de articulações, evolução temporal, padrão mecânico ou inflamatório.", "Definir hipóteses e conduta: formulação etiológica, prioridade e investigação dirigida.", "Sinais de alarme (febre, déficit neurológico, trauma ou perda funcional aguda) mudam a prioridade imediatamente."]}, {"t": "As quatro perguntas fundamentais (slide 3)", "sub": ["1. Localizar o processo: articular ou periarticular? dor referida de outro segmento?", "2. Confirmar artrite: há sinais flogísticos objetivos? derrame ou espessamento sinovial?", "3. Caracterizar o padrão: quantas articulações? qual o ritmo temporal da dor?", "4. Reconhecer urgência: sinais de alarme locais ou sistêmicos? risco de dano articular irreversível?"]}, {"t": "Artralgia, artrite e periarticular (slide 4)", "sub": ["Artralgia: dor subjetiva na articulação, sem sinais inflamatórios visíveis; mobilidade passiva preservada.", "Artrite: inflamação objetiva, com sinovite ou derrame, calor local e limitação dolorosa ativa e passiva. O rubor pode estar ausente.", "Periarticular: tendões, bursas e enteses; dor focal à palpação e dor com contrarresistência.", "Erro comum: aumento de volume isolado exige palpação; pode ser bursite, edema subcutâneo ou proliferação óssea."]}]}, {"titulo": "2. Número, distribuição e evolução (slides 5 a 6)", "pontos": [{"t": "Topografia (slide 5)", "sub": ["Monoartrite: 1 articulação; prioridade diferencial primária.", "Oligoartrite: 2 a 4 articulações; frequentemente assimétrica (ex.: espondiloartrites).", "Poliartrite: 5 ou mais articulações; pesquisar padrão simétrico (ex.: artrite reumatoide).", "Simetria: compare articulações homólogas. Eixo axial: avalie coluna e sacroilíacas."]}, {"t": "Dimensão temporal (slide 6)", "sub": ["Aditiva: sintomas se somam a novas áreas; as anteriores continuam inflamadas.", "Migratória: a inflamação muda de local; a articulação anterior melhora quando a nova inflama.", "Episódica: surtos explosivos e autolimitados, com períodos intercríticos assintomáticos.", "Registre início exato e duração real dos sintomas."]}, {"t": "Funil diagnóstico: contagem e topografia (slide 12)", "sub": ["Contar as articulações inflamadas com precisão.", "Mapear a distribuição: simetria, eixo axial versus periférico.", "Integrar o tempo: agudo versus persistente.", "Objetivo: reconhecer padrões rápido, para diagnóstico diferencial e triagem de urgência."]}]}, {"titulo": "3. Padrão inflamatório versus mecânico (slides 7 e 8)", "pontos": [{"t": "Comparação (slide 7)", "sub": ["Inflamatório: rigidez matinal prolongada (>60 min); piora com repouso e melhora com movimento; sinovite amolecida, derrame e calor; fadiga, febre e perda ponderal são frequentes.", "Mecânico: rigidez breve ou ausente (<30 min); piora com movimento e carga e melhora no repouso; crepitação, aumento ósseo endurecido e bloqueio; ausência de manifestações sistêmicas.", "Atenção à sobreposição: a osteoartrite pode ter inflamação local episódica (derrame e calor). O diagnóstico exige avaliar a evolução global."]}, {"t": "Pistas extra-articulares (slide 8)", "sub": ["Sistêmico: febre, fadiga, perda de peso.", "Ocular: olho vermelho doloroso sugere uveíte.", "Tegumento: placas eritematodescamativas (psoríase) e fenômeno de Raynaud.", "Geniturinário: uretrite ou infecção recente.", "Gastrointestinal: diarreia crônica, disenteria ou doença inflamatória intestinal.", "A queixa articular é o centro, mas a resposta pode estar no sistema."]}]}, {"titulo": "4. Monoartrite aguda: a prioridade é a infecção (slides 9 e 10)", "pontos": [{"t": "Cenário de alta prioridade (slide 9)", "sub": ["Trauma: história mecânica clara; hemartrose suspeita.", "Cristais: início explosivo; história prévia típica.", "Infecção (artrite séptica): evolução rápida e risco de destruição cartilaginosa. É prioridade clínica absoluta.", "Infecção é diagnóstico de exclusão obrigatório em toda monoartrite aguda inflamatória."]}, {"t": "Limites da semiologia (slide 10)", "sub": ["Achados locais: dor intensa e calor, tumefação visível ou palpável, limitação dolorosa severa ativa e passiva.", "Ausência de febre não exclui infecção. Exames de sangue normais também não excluem infecção.", "Nenhum achado clínico isolado substitui a avaliação imediata e a artrocentese diagnóstica."]}, {"t": "Condutas relacionadas (aula 8)", "sub": ["Artrite séptica: antibioticoterapia empírica e artrocentese detalhadas na aula 8, aba Condutas/Medicações.", "Gonococo e outras causas infecciosas de artrite: ver condutas da aula 8."]}]}, {"titulo": "5. Cristais: gota e CPPD (slides 11 a 13)", "pontos": [{"t": "Gota (slide 11)", "sub": ["Protótipo do padrão episódico: podagra (1ª metatarsofalangiana), sinais inflamatórios exuberantes, instalação em poucas horas.", "Evolução: fase 1 início abrupto; fase 2 crise autolimitada (dias a semanas); fase 3 recorrência com intervalos cada vez menores; fase 4 deposição crônica (tofos e dano estrutural).", "Erro comum: uricemia isolada não encerra nem confirma o diagnóstico; a análise do líquido sinovial (cristais) é soberana."]}, {"t": "CPPD: o imitador (slide 13)", "sub": ["Gota: urato monossódico; 1ª metatarsofalangiana; tofos.", "CPPD: pirofosfato de cálcio; joelho e punho; condrocalcinose.", "Alerta: a crise de CPPD (pseudogota) pode imitar perfeitamente gota ou artrite séptica."]}, {"t": "Trauma, hemartrose e líquido sinovial (slide 14)", "sub": ["Mecanismo: trauma mecânico ou relação temporal direta. Contexto: distúrbios hemorrágicos ou anticoagulantes.", "Análise: cultura, celularidade e pesquisa de cristais.", "Derrame sem explicação óbvia exige investigação invasiva. Hemartrose exige exclusão imediata de lesão estrutural grave.", "Cristais não excluem infecção: contagem intermediária orienta, mas não permite descartar artrite séptica isoladamente."]}]}, {"titulo": "6. Monoartrite persistente e oligoartrite (slides 15 e 16)", "pontos": [{"t": "Ponto de reavaliação (slide 15)", "sub": ["Aguda: menos de 6 semanas. Persistente: reavaliar.", "Confirmar a presença contínua de inflamação objetiva; revisar exposições, tratamentos prévios e episódios passados.", "Causas de persistência: infecção indolente (tuberculose, fungos); doença inflamatória inicial; artropatia por cristais na fase crônica; imitadores mecânicos ou periarticulares.", "Mudança de conduta: se não melhora, o algoritmo reinicia. Persistência não garante etiologia benigna."]}, {"t": "Oligoartrite e padrão periférico (slide 16)", "sub": ["Definição: 2 a 4 articulações.", "Geografia típica: membros inferiores, com padrão frequentemente assimétrico.", "Entesite (ex.: calcâneo) e dactilite (dedo em salsicha) são altamente sugestivas de espondiloartrite."]}]}, {"titulo": "7. Espondiloartrites, poliartrite e artrite psoriásica (slides 17 a 20)", "pontos": [{"t": "Espondiloartrites (slide 17)", "sub": ["Combine lombalgia de ritmo inflamatório com artrite periférica.", "Pele: psoríase. Olho: uveíte anterior (alarme: dor e fotofobia). Intestino: doença inflamatória intestinal.", "A busca por manifestações extra-articulares é obrigatória no exame articular. Queixas sistêmicas podem anteceder, acompanhar ou suceder o quadro."]}, {"t": "Poliartrite (slide 18)", "sub": ["Confirme no mínimo 5 articulações com sinovite verdadeira, não apenas poliartralgia.", "Quadro recente: avaliar febre, epidemiologia e infecções virais.", "Quadro persistente: orientar para doenças autoimunes, evolução aditiva e contexto sistêmico."]}, {"t": "Artrite reumatoide (slide 19)", "sub": ["Sinovite persistente, aditiva e frequentemente simétrica; rigidez matinal maior que 1 hora.", "Início tipicamente nas pequenas articulações das mãos (IFP, MCF e punhos), antes de grandes danos.", "Conduta: encaminhamento precoce. Não aguarde deformidades nem sorologia positiva."]}, {"t": "Artrite psoriásica (slide 20)", "sub": ["Padrões: de oligoartrite assimétrica a poliartrite simétrica, mimetizando a AR.", "Achados-chave: envolvimento de articulações distais (diferencial marcante), dactilite difusa, depressões cupuliformes e onicólise.", "A inspeção da pele e das unhas faz parte do exame articular."]}, {"t": "Condutas relacionadas (aula 8)", "sub": ["Artrite reumatoide: metotrexato e encaminhamento detalhados na aula 8, aba Condutas/Medicações."]}]}, {"titulo": "8. Doenças do tecido conjuntivo e contexto infeccioso (slides 21 e 22)", "pontos": [{"t": "Artrite sistêmica (slide 21)", "sub": ["Artralgia ou artrite raramente ocorrem isoladas; o quadro articular pode ser passageiro de uma inflamação sistêmica (ex.: lúpus, esclerodermia).", "Pele e mucosas: fotossensibilidade, úlceras orais, exantemas.", "Vasculatura: fenômeno de Raynaud (isquemia digital episódica).", "Sintomas secos: xeroftalmia e xerostomia (síndrome de Sjögren)."]}, {"t": "Cronologia infecciosa (slide 22)", "sub": ["A cronologia (antes, durante ou depois) é o principal divisor de águas.", "Viral (ex.: chikungunya): simultânea; febre aguda, exantema, contexto epidemiológico.", "Artrite reativa: pós-infecciosa, em semanas; diarreia prévia ou uretrite; preferência por membros inferiores.", "Infecção articular direta (séptica): atual; acometimento mono ou oligoarticular agudo, dor severa e perda funcional.", "Antecedente infeccioso recente não dispensa o exame da articulação atual."]}]}, {"titulo": "9. Aumento de volume, distribuição anatômica e dor referida (slides 25 a 28)", "pontos": [{"t": "Osteoartrite e padrão mecânico (slide 25)", "sub": ["Dor agravada por carga e uso; rigidez breve (geralmente <30 min) após inatividade.", "Exame: crepitação palpável ou audível e limitação de amplitude; aumento de volume por osteófitos.", "Pode haver derrame, mas piora rápida ou calor muito intenso exige rever a hipótese."]}, {"t": "Mãos: distribuição anatômica (slide 26)", "sub": ["Osteoartrite (mecânico): nódulos de Heberden (IFD), nódulos de Bouchard (IFP), rizartrose (base do polegar).", "Artrite reumatoide (inflamatório): punhos e MCF (alvos primários), IFP; poupa as IFD na fase inicial."]}, {"t": "Natureza do aumento de volume (slide 27)", "sub": ["Osteoartrite: consistência dura e nodular, irreversível, indolor à palpação leve, sem calor irradiado significativo.", "Sinovite (AR): consistência elástica, 'esponjosa'; dor à palpação das interlinhas; frequentemente com calor e derrame.", "Não espere deformidades: o diagnóstico de artrite inflamatória baseia-se na sinovite inicial."]}, {"t": "Joelho, quadril e dor referida (slide 28)", "sub": ["Quadril: dor tipicamente inguinal, com limitação de rotação interna e abdução.", "Joelho: dor relacionada à marcha ou às escadas; procure crepitação, desalinhamento (varo ou valgo) e bloqueio mecânico.", "Vetor de dor referida: patologias do quadril frequentemente referem dor exclusivamente no joelho. Sempre examine a articulação proximal à queixa."]}, {"t": "Diferenciação das mãos e do volume (slides 26 e 27)", "sub": ["Sinovite (inflamatório): tumefação amolecida, elástica ou flutuante; MCF e IFP; artropatias inflamatórias crônicas (ex.: AR).", "Proliferação óssea (degenerativo): nódulos rígidos e duros; osteoartrite."]}]}, {"titulo": "10. Periarticular versus articular e red flags (slides 29, 30 e 36)", "pontos": [{"t": "Simulador periarticular (slide 29)", "sub": ["Estruturas extra-articulares imitam queixas articulares.", "Localização: dor focal e pontual (inserção tendínea, bursa), não difusa na interlinha.", "Aumento de volume assimétrico, restrito à estrutura (bursite pré-patelar versus derrame intra-articular global).", "A chave semiológica é a biomecânica do movimento."]}, {"t": "Matriz de diferenciação cinética (slide 30)", "sub": ["Dor à palpação: difusa na interlinha (articular) x focal no tendão ou bursa (periarticular).", "Movimento passivo: doloroso e limitado (articular) x preservado (periarticular).", "Movimento resistido: indolor se a cápsula estiver intacta (articular) x altamente doloroso (periarticular).", "Edema: global com contorno articular perdido (articular) x localizado, como abaulamento de bursa (periarticular)."]}, {"t": "Red flags (slide 36)", "sub": ["Sistêmico ou infeccioso: febre, imunossupressão, antecedente oncológico recente, perda ponderal inexplicada.", "Traumático: deformidade óssea aguda, alteração de pulso distal, déficit motor ou sensitivo após trauma.", "Ocular: olho vermelho doloroso, fotofobia ou visão turva (risco de uveíte anterior aguda: oftalmologia no mesmo dia).", "Axial ou neurológico: lombalgia com déficit motor progressivo, retenção urinária ou anestesia em sela."]}]}, {"titulo": "11. Erros comuns e raciocínio integrado (slides 37 e 38)", "pontos": [{"t": "Erros comuns na prática (slide 37)", "sub": ["Registrar qualquer dor como artrite: diferencie artralgia (sintoma) de artrite (sinal objetivo).", "Assumir que simetria é regra absoluta: o início pode ser assimétrico.", "Excluir infecção porque não há febre: monoartrites quentes e incapacitantes são puncionadas independentemente da temperatura.", "Atribuir piora aguda a osteoartrite prévia: a piora abrupta exige reavaliação completa."]}, {"t": "Fluxo integrado (slide 38)", "sub": ["1) Acesso: queixa osteomioarticular; sinais de alarme (infecção, trauma, neuro) pedem avaliação imediata.", "2) Confirmação: articular (inflamação) ou tendão ou bursa (periarticular)?", "3) Topografia: distribuição e contagem (mono, oligo, poli).", "4) Cinética: mecânico (carga e uso) versus inflamatório (repouso e rigidez).", "5) Integração sistêmica: pele, olhos, TGI, vias urinárias.", "6) Conduta: hipóteses dirigidas e nível de prioridade (ambulatório versus urgência)."]}]}, {"titulo": "12. Síntese e casos (slides 23, 31 a 35)", "pontos": [{"t": "Síntese por número de articulações (slide 23)", "sub": ["1 articulação (monoartrite): infecção, cristais, trauma.", "2 a 4 (oligoartrite): assimetria, MMII, entesite, eixo axial (espondiloartrites).", "5 ou mais (poliartrite): recente (viral ou reativa) ou persistente (AR, psoríase, colagenoses).", "Raciocínio final: localizar a dor, confirmar a inflamação objetiva, mapear o padrão estrutural e identificar a urgência."]}, {"t": "Triagem e prioridades (slide 35)", "sub": ["Urgência imediata (emergência): monoartrite intensamente dolorosa e quente; suspeita de infecção; trauma com deformidade; déficit neurovascular. Conduta no mesmo dia (PS ou ortopedia).", "Avaliação especializada rápida (ambulatorial): sinovite persistente; poliartrite de pequenas articulações; rigidez matinal prolongada. Encaminhar à reumatologia para evitar dano irreversível."]}]}], "glossario": [{"termo": "Podagra", "epônimo": "", "tecnica": "Inspeção e palpação da 1ª metatarsofalângica", "definicao": "Acometimento da primeira metatarsofalângica, com sinais inflamatórios exuberantes e instalação em poucas horas: protótipo da crise de gota.", "slide": 11}, {"termo": "CPPD (pseudogota)", "epônimo": "", "tecnica": "Análise do líquido sinovial", "definicao": "Cristais de pirofosfato de cálcio, com alvo em joelho e punho e condrocalcinose; imita gota ou artrite séptica.", "slide": 13}, {"termo": "Condrocalcinose", "epônimo": "", "tecnica": "Imagem articular", "definicao": "Calcificação da cartilagem, pista de imagem da CPPD.", "slide": 13}, {"termo": "Dactilite (dedo em salsicha)", "epônimo": "", "tecnica": "Inspeção dos dedos", "definicao": "Edema difuso do dedo; altamente sugestiva de espondiloartrite, junto com a entesite.", "slide": 16}, {"termo": "Entesite", "epônimo": "", "tecnica": "Palpação da inserção tendínea (ex.: calcâneo)", "definicao": "Inflamação da inserção do tendão ou ligamento no osso; sugere espondiloartrite.", "slide": 16}, {"termo": "Depressões cupuliformes e onicólise", "epônimo": "", "tecnica": "Inspeção das unhas", "definicao": "Pistas ungueais de artrite psoriásica, junto com a dactilite.", "slide": 20}, {"termo": "Fenômeno de Raynaud", "epônimo": "Raynaud", "tecnica": "Anamnese e observação dos dedos ao frio e ao estresse", "definicao": "Isquemia digital episódica, com palidez, cianose e rubor. Associado a doenças do tecido conjuntivo.", "slide": 21}, {"termo": "Síndrome de Sjögren (sintomas secos)", "epônimo": "Sjögren", "tecnica": "Anamnese de xeroftalmia e xerostomia", "definicao": "Xeroftalmia e xerostomia em doenças do tecido conjuntivo.", "slide": 21}, {"termo": "Nódulos de Heberden", "epônimo": "Heberden", "tecnica": "Palpação da IFD", "definicao": "Nódulos ósseos duros em IFD: osteoartrite. Diferente da sinovite da AR, que poupa as IFD na fase inicial.", "slide": 26}, {"termo": "Nódulos de Bouchard", "epônimo": "Bouchard", "tecnica": "Palpação da IFP", "definicao": "Nódulos ósseos em IFP: osteoartrite.", "slide": 26}], "manobras": [{"nome": "Contagem e distribuição articular", "epônimo": null, "como": "Conte as articulações inflamadas e mapeie a distribuição: simetria, eixo axial e articulações periféricas.", "alterado": "1 articulação (monoartrite), 2 a 4 (oligoartrite), 5 ou mais (poliartrite).", "significado": "Define o padrão sindrômico e a prioridade diferencial.", "slide": 5}, {"nome": "Investigação de manifestações extra-articulares", "epônimo": null, "como": "Interroge e examine olhos, pele, unhas, intestino e vias urinárias durante o exame articular.", "alterado": "Olho vermelho doloroso, psoríase, diarreia crônica, uretrite ou fenômeno de Raynaud.", "significado": "Sugere espondiloartrite, artrite psoriásica, doença inflamatória intestinal ou colagenose.", "slide": 8}, {"nome": "Artrocentese diagnóstica", "epônimo": null, "como": "Coleta de líquido sinovial para celularidade, Gram, cultura e pesquisa de cristais.", "alterado": "Contagem celular alta, cultura positiva ou cristais específicos.", "significado": "Confirma infecção ou cristais. Nenhum achado clínico isolado substitui a artrocentese em monoartrite aguda inflamatória.", "slide": 10}, {"nome": "Palpação do aumento de volume", "epônimo": null, "como": "Palpe a consistência e a relação com a interlinha, e procure calor e flutuação.", "alterado": "Consistência elástica ou esponjosa com dor às interlinhas (sinovite); consistência dura e nodular (osteófito).", "significado": "Diferencia sinovite de proliferação óssea e de edema subcutâneo.", "slide": 27}, {"nome": "Matriz de diferenciação cinética", "epônimo": null, "como": "Compare movimento ativo, passivo e resistido, e a palpação, entre a articulação e a estrutura periarticular.", "alterado": "Passivo limitado com resistido indolor sugere articular (cápsula); passivo preservado com resistido doloroso sugere tendão ou bursa.", "significado": "Separa doença articular verdadeira de periarticular, e orienta a investigação.", "slide": 30}], "caso": {"titulo": "Casos integradores de síndromes articulares", "perfil": "Monoartrite aguda, poliartrite persistente, cronologia infecciosa, espondiloartrite, dor referida do quadril e triagem de prioridade.", "etapas": [{"titulo": "Etapa 1 · Monoartrite aguda em paciente com gota prévia (slide 31)", "texto": "Paciente de 67 anos, com joelho direito doloroso há 24 horas. Ao exame: calor intenso, derrame visível, mobilização ativa e passiva impossibilitadas por dor extrema e incapacidade de apoio. Está afebril e tem episódios prévios diagnosticados como gota.", "perguntas": [{"pergunta": "Qual é a síndrome e a prioridade absoluta de investigação?", "alternativas": ["Poliartrite persistente, com prioridade para o perfil imunológico", "Osteoartrite agudizada, com prioridade para radiografia simples", "Monoartrite aguda, com prioridade para descartar infecção", "Lombalgia irradiada, com prioridade para ressonância magnética", "Tendinite patelar, com prioridade para infiltração local"], "gabarito": "C", "justificativa": "Monoartrite aguda intensa e quente exige descartar artrite séptica como prioridade absoluta, com artrocentese diagnóstica. A história de gota não explica o quadro sozinha.", "erradas": {"A": "Poliartrite exige cinco ou mais articulações; aqui há apenas uma.", "B": "Radiografia não é a prioridade diante da suspeita de infecção.", "D": "O quadro é articular e agudo, e não lombar.", "E": "Tendinite não explica calor, derrame e incapacidade de apoio."}}, {"pergunta": "Por que a ausência de febre não encerra a investigação nesse paciente?", "alternativas": ["A febre ocorre apenas na gota e jamais em infecção articular", "A infecção pode ocorrer sem febre e com exames normais", "A febre é sinal obrigatório de artrite reumatoide ativa", "O derrame visível exclui infecção em articulação grande", "A gota prévia protege o joelho contra infecção bacteriana"], "gabarito": "B", "justificativa": "Ausência de febre e exames de sangue normais não excluem infecção; nenhum achado clínico isolado substitui a avaliação imediata e a artrocentese.", "erradas": {"A": "A febre não é exclusiva da gota e a infecção articular também a causa quando presente.", "C": "A febre não é sinal obrigatório de artrite reumatoide.", "D": "O derrame não exclui infecção; ele exige análise do líquido.", "E": "Gota prévia não protege contra infecção e a osteoartrite também não."}}]}, {"titulo": "Etapa 2 · Resolução e análise do líquido (slides 14 e 32)", "texto": "A equipe puncionou o joelho. O líquido tem 40.000 leucócitos/mm³ e cristais de urato monossódico negativamente birrefringentes. A cultura ainda não está disponível. O paciente pergunta se a gota explica tudo.", "perguntas": [{"pergunta": "Qual é a interpretação mais segura dos achados do líquido sinovial?", "alternativas": ["Gota confirmada e infecção excluída, pela presença de cristais", "Cristais não excluem infecção; a contagem não afasta séptica", "Artrite séptica confirmada, pela contagem acima de 10.000/mm³", "Osteoartrite com derrame, pelo aspecto inflamatório do líquido", "Pseudogota, pela presença de cristais birrefringentes no líquido"], "gabarito": "B", "justificativa": "Cristais não excluem infecção, e uma contagem intermediária orienta, mas não permite descartar artrite séptica isoladamente; a cultura define o manejo.", "erradas": {"A": "Cristais podem coexistir com infecção; a cultura decide.", "C": "A contagem isolada não confirma infecção sem cultura.", "D": "Osteoartrite não explica o quadro inflamatório agudo com cristais.", "E": "Pseudogota tem pirofosfato de cálcio; urato monossódico indica gota."}}, {"pergunta": "Qual é a diferença entre gota e CPPD (pseudogota) quanto ao cristal e ao alvo articular?", "alternativas": ["Gota: pirofosfato de cálcio; CPPD: urato monossódico", "Ambas têm urato monossódico, diferindo apenas pela idade", "Gota: urato, com podagra; CPPD: pirofosfato, joelho e punho", "Gota: joelho e punho; CPPD: primeira metatarsofalângica", "Ambas têm pirofosfato, diferindo apenas pela contagem celular"], "gabarito": "C", "justificativa": "Gota é urato monossódico, com podagra e tofos; CPPD é pirofosfato de cálcio, com joelho e punho e condrocalcinose. A crise de CPPD pode imitar gota ou artrite séptica.", "erradas": {"A": "Os cristais estão invertidos.", "B": "O cristal é diferente, e não só a idade.", "D": "A localização está invertida.", "E": "O cristal diferencia, e a contagem não define a doença."}}]}, {"titulo": "Etapa 3 · Poliartrite persistente (slide 33)", "texto": "Paciente de 42 anos, com queixas há 3 meses. Tumefação bilateral de punhos e de pequenas articulações das mãos, com dor à palpação das MCF e IFP. Rigidez matinal de 90 minutos e dificuldade motora importante para fechar as mãos ao acordar.", "perguntas": [{"pergunta": "Qual é o padrão sindrômico mais provável?", "alternativas": ["Poliartrite simétrica persistente, sugestiva de artrite reumatoide", "Padrão mecânico por osteoartrite de mãos, com nódulos duros", "Monoartrite aguda, com necessidade de artrocentese imediata", "Oligoartrite assimétrica de membros inferiores, com entesite e dactilite", "Periarticular de punho, com tendinite focal e dor resistida"], "gabarito": "A", "justificativa": "Poliartrite simétrica persistente, aditiva, de pequenas articulações, com rigidez maior que 1 hora, sugere artrite reumatoide.", "erradas": {"B": "Rigidez longa e sinovite não são padrão mecânico.", "C": "Há mais de uma articulação, e o quadro é persistente, não agudo.", "D": "O padrão é simétrico e poliarticular, e não oligoarticular assimétrico.", "E": "A dor é sinovial e difusa, e não focal em tendão."}}, {"pergunta": "Qual característica do exame sustenta sinovite em vez de aumento ósseo?", "alternativas": ["Nódulo ósseo duro e indolor nas interfalângicas distais", "Deformidade em pescoço de cisne, sem dor associada ao exame", "Massa flutuante e indolor na bainha tendínea do punho", "Consistência elástica, dor às interlinhas e calor local", "Edema com cacifo restrito ao dorso da mão, sem calor"], "gabarito": "D", "justificativa": "Sinovite tem consistência amolecida, elástica ou esponjosa, dor à palpação das interlinhas e frequentemente calor; osteófitos são duros e indolores.", "erradas": {"A": "Nódulo ósseo duro e indolor indica osteoartrite (Heberden).", "B": "Deformidade sem dor é tardia e não define a sinovite inicial.", "C": "Massa flutuante e indolor sugere cisto ou ganglion.", "E": "Edema com cacifo restrito ao dorso é edema subcutâneo, e não sinovite."}}]}, {"titulo": "Etapa 4 · Erro frequente no encaminhamento (slide 34)", "texto": "A equipe considera aguardar as deformidades visíveis ou a sorologia (fator reumatoide) para encaminhar a paciente da etapa anterior. O fator reumatoide veio negativo.", "perguntas": [{"pergunta": "Qual é a conduta correta?", "alternativas": ["Aguardar deformidades visíveis, pois o diagnóstico depende delas", "Aguardar seis meses de evolução antes de qualquer encaminhamento", "Encaminhar já: sinovite evidente basta, sorologia não afasta", "Aguardar a sorologia positiva para evitar encaminhamentos inúteis", "Encaminhar apenas se houver febre associada ao quadro articular"], "gabarito": "C", "justificativa": "Sinovite clínica evidente justifica encaminhamento especializado rápido; a sorologia negativa não afasta a suspeita nem deve adiar a avaliação.", "erradas": {"A": "Deformidades são tardias; o diagnóstico se baseia na sinovite inicial.", "B": "Atrasar o encaminhamento causa dano estrutural irreversível.", "D": "A sorologia positiva não é pré-requisito para encaminhar.", "E": "Febre não é critério para encaminhar a suspeita de artrite reumatoide."}}]}, {"titulo": "Etapa 5 · Cronologia infecciosa (slide 22)", "texto": "Homem de 25 anos apresenta dor e edema de joelho e tornozelo direitos há 5 dias, com início 3 semanas após um quadro de diarreia. Não há febre. Refere ainda uretrite na semana anterior e olho vermelho.", "perguntas": [{"pergunta": "Qual é o diagnóstico mais provável, pela cronologia?", "alternativas": ["Artrite viral simultânea, com exantema e febre aguda", "Artrite séptica direta, com início atual e dor muito intensa", "Artrite reativa, pós-infecciosa, em membros inferiores", "Gota, com podagra e hiperuricemia, sem relação com infecção", "Artrite reumatoide, com poliartrite simétrica das mãos"], "gabarito": "C", "justificativa": "Artrite reativa é pós-infecciosa, de semanas, com preferência por membros inferiores e antecedente de diarreia ou uretrite; a séptica tem timing atual.", "erradas": {"A": "A artrite viral é simultânea, com febre e exantema, e não semanas depois.", "B": "A séptica é aguda, mono ou oligoarticular, com dor severa e timing atual.", "D": "Gota não explica a cronologia nem o antecedente de diarreia.", "E": "A artrite reumatoide é simétrica, de pequenas articulações."}}, {"pergunta": "Antecedente infeccioso recente dispensa o exame da articulação atual?", "alternativas": ["Sim, pois a artrite reativa nunca precisa de punção", "Sim, pois o antecedente explica toda monoartrite posterior", "Não, pois a infecção direta ainda deve ser excluída", "Não, pois o antecedente aumenta o risco apenas de gota", "Sim, desde que o paciente esteja afebril ao exame"], "gabarito": "C", "justificativa": "O antecedente infeccioso não dispensa o exame da articulação atual nem exclui infecção bacteriana direta.", "erradas": {"A": "A artrite reativa não dispensa o exame articular.", "B": "O antecedente não explica automaticamente a artrite atual.", "D": "O antecedente não está relacionado apenas à gota.", "E": "A ausência de febre não exclui infecção articular."}}]}, {"titulo": "Etapa 6 · Espondiloartrite com manifestações extra-articulares (slides 16, 17 e 36)", "texto": "Homem de 29 anos, com dor lombar de ritmo inflamatório há 3 anos, oligoartrite de tornozelo e joelho direitos, dactilite do segundo pododáctilo e dor à palpação da inserção do tendão de Aquiles. Há 2 meses, teve olho vermelho doloroso com fotofobia.", "perguntas": [{"pergunta": "Qual grupo diagnóstico agrupa entesite, dactilite e lombalgia inflamatória?", "alternativas": ["Espondiloartrite, com entesite e dactilite", "Artrite reumatoide, com sinovite simétrica das mãos", "Osteoartrite, com dor mecânica e rigidez breve", "Gota tofácea, com crises explosivas e tofos", "Lúpus eritematoso, com artrite não erosiva e rash"], "gabarito": "A", "justificativa": "Entesite e dactilite em oligoartrite assimétrica de membros inferiores, com lombalgia inflamatória e uveíte, sugerem espondiloartrite.", "erradas": {"B": "A artrite reumatoide é simétrica e de pequenas articulações.", "C": "A osteoartrite tem padrão mecânico e rigidez breve.", "D": "A gota tem crises explosivas e tofos, sem lombalgia inflamatória.", "E": "O lúpus cursa com artrite não erosiva e manifestações sistêmicas diversas."}}, {"pergunta": "Qual é a conduta para o olho vermelho doloroso com fotofobia?", "alternativas": ["Colírio lubrificante e reavaliação em duas semanas", "Antibiótico tópico por sete dias, sem avaliação prévia", "Corticoide oral e alta, sem encaminhamento especializado", "Observação ambulatorial, pois a artrite explica o quadro", "Oftalmologia no mesmo dia, pelo risco de uveíte"], "gabarito": "E", "justificativa": "Olho vermelho doloroso, fotofobia ou visão turva em quadro articular sugere uveíte anterior aguda: oftalmologia no mesmo dia.", "erradas": {"A": "Lubrificante e espera atrasam o diagnóstico de uveíte.", "B": "Antibiótico tópico não trata uveíte e pode mascarar o quadro.", "C": "Corticoide oral sem avaliação oftalmológica não é adequado.", "D": "A dor articular não explica olho vermelho doloroso com fotofobia."}}]}, {"titulo": "Etapa 7 · Joelho com dor referida do quadril (slide 28)", "texto": "Mulher de 67 anos queixa-se de dor no joelho direito, pior em escadas. O joelho tem amplitude preservada, mas há limitação da rotação interna e da abdução do quadril direito, com dor inguinal.", "perguntas": [{"pergunta": "Qual é a interpretação do quadro e a regra de exame?", "alternativas": ["Dor referida do quadril; examine a articulação proximal", "Lesão meniscal isolada; examine apenas o joelho dolorido", "Bursite pré-patelar; examine apenas a face anterior do joelho", "Neuropatia periférica; examine os reflexos dos pés", "Osteoartrite isolada do joelho; examine somente o derrame"], "gabarito": "A", "justificativa": "Dor no joelho com limitação de rotação interna e abdução do quadril e dor inguinal sugere dor referida do quadril; sempre examine a articulação proximal à queixa.", "erradas": {"B": "Não há dado que sustente lesão meniscal isolada.", "C": "A bursite pré-patelar tem aumento de volume anterior localizado.", "D": "A neuropatia não explica a limitação dos movimentos do quadril.", "E": "O exame do quadril alterado mostra que o problema não é só do joelho."}}]}, {"titulo": "Etapa 8 · Triagem e prioridade (slide 35)", "texto": "Dois pacientes chegam ao pronto atendimento. O primeiro tem monoartrite intensamente dolorosa e quente, com perda funcional aguda. O segundo tem sinovite persistente de pequenas articulações das mãos e rigidez matinal prolongada há dois meses.", "perguntas": [{"pergunta": "Qual é a prioridade correta para cada paciente?", "alternativas": ["Ambos devem aguardar avaliação ambulatorial eletiva de rotina", "Primeiro: reumatologia em 3 meses; segundo: urgência no mesmo dia", "Primeiro: urgência no mesmo dia; segundo: reumatologia rápida", "Ambos devem receber corticoide e alta, sem outra avaliação", "Primeiro: fisioterapia; segundo: ortopedia de urgência"], "gabarito": "C", "justificativa": "Monoartrite quente e incapacitante com suspeita de infecção exige urgência no mesmo dia; sinovite persistente de pequenas articulações exige encaminhamento prioritário à reumatologia.", "erradas": {"A": "A monoartrite quente não pode esperar avaliação eletiva.", "B": "As prioridades estão invertidas.", "D": "Corticoide e alta não são adequados antes de excluir infecção.", "E": "Fisioterapia não resolve monoartrite quente; a segunda é caso reumatológico."}}]}]}, "imagens": [{"slide": 2, "titulo": "Funil clínico das síndromes articulares", "explicacao": "Reconhecer a queixa, descrever a síndrome e definir hipóteses e conduta. Sinais de alarme mudam a prioridade."}, {"slide": 3, "titulo": "As quatro perguntas fundamentais", "explicacao": "Localizar o processo, confirmar artrite, caracterizar o padrão e reconhecer urgência."}, {"slide": 4, "titulo": "Artralgia, artrite e periarticular", "explicacao": "Artralgia é sintoma; artrite é sinal objetivo de inflamação; periarticular é dor focal de tendão, bursa ou entese."}, {"slide": 5, "titulo": "Número e distribuição", "explicacao": "Monoartrite, oligoartrite e poliartrite; padrão simétrico ou assimétrico; eixo axial."}, {"slide": 6, "titulo": "Dimensão temporal", "explicacao": "Evolução aditiva, migratória e episódica."}, {"slide": 7, "titulo": "Padrão inflamatório versus mecânico", "explicacao": "Rigidez matinal, piora com repouso ou carga, sinovite, derrame e sinais sistêmicos. Atenção à sobreposição."}, {"slide": 9, "titulo": "Monoartrite aguda: prioridade", "explicacao": "Trauma, cristais e infecção. Infecção é diagnóstico de exclusão obrigatório."}, {"slide": 10, "titulo": "Artrite séptica e limites da semiologia", "explicacao": "Ausência de febre e exames normais não excluem infecção. Artrocentese diagnóstica."}, {"slide": 11, "titulo": "Gota: padrão episódico", "explicacao": "Podagra, evolução em quatro fases e análise do líquido sinovial."}, {"slide": 13, "titulo": "CPPD: imitador clínico", "explicacao": "Pirofosfato de cálcio, joelho e punho; pode imitar gota ou artrite séptica."}, {"slide": 15, "titulo": "Monoartrite persistente", "explicacao": "Confirmar inflamação contínua e reavaliar a etiologia após seis semanas."}, {"slide": 16, "titulo": "Oligoartrite e padrão periférico", "explicacao": "Entesite e dactilite são sugestivas de espondiloartrite."}, {"slide": 17, "titulo": "Espondiloartrites", "explicacao": "Lombalgia inflamatória, artrite periférica e manifestações extra-articulares."}, {"slide": 19, "titulo": "Artrite reumatoide: padrão aditivo simétrico", "explicacao": "Pequenas articulações das mãos; encaminhamento precoce."}, {"slide": 20, "titulo": "Artrite psoriásica", "explicacao": "Dactilite, onicólise e envolvimento distal."}, {"slide": 21, "titulo": "Doenças do tecido conjuntivo", "explicacao": "Raynaud, úlceras orais e sintomas secos."}, {"slide": 22, "titulo": "Contexto infeccioso", "explicacao": "Cronologia: viral (simultânea), reativa (semanas) e séptica (atual)."}, {"slide": 25, "titulo": "Osteoartrite: padrão mecânico", "explicacao": "Crepitação, rigidez breve e osteófitos."}, {"slide": 26, "titulo": "Mãos: distribuição anatômica", "explicacao": "Heberden, Bouchard e rizartrose versus punhos, MCF e IFP da AR."}, {"slide": 27, "titulo": "Natureza do aumento de volume", "explicacao": "Osteófito versus sinovite."}, {"slide": 28, "titulo": "Joelho, quadril e dor referida", "explicacao": "Sempre examine a articulação proximal à queixa."}, {"slide": 29, "titulo": "Simulador periarticular", "explicacao": "Estruturas extra-articulares imitam queixas articulares."}, {"slide": 30, "titulo": "Matriz de diferenciação cinética", "explicacao": "Articular x periarticular pelos movimentos ativo, passivo e resistido."}, {"slide": 36, "titulo": "Red flags", "explicacao": "Sistêmicos, traumáticos, oculares e axiais."}, {"slide": 38, "titulo": "Raciocínio sindrômico integrado", "explicacao": "Fluxo de seis passos até a conduta."}], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Monoartrite aguda de joelho, quente e com derrame, em paciente afebril com episódios prévios de gota. Qual é a prioridade absoluta?", "alternativas": ["Excluir artrite séptica por artrocentese, mesmo sem febre", "Confirmar gota com dosagem de ácido úrico e iniciar colchicina", "Ressonância de joelho para avaliar lesão meniscal associada", "Corticoide oral por trinta dias e reavaliação clínica", "Eletroneuromiografia para descartar neuropatia periférica"], "gabarito": "A", "justificativa": "Infecção é diagnóstico de exclusão obrigatório em toda monoartrite aguda; ausência de febre e exames normais não a afastam.", "epônimo": null, "tecnica": "Artrite séptica", "slide": 10}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Qual é a diferença de imagem e de alvo articular entre gota e pseudogota (CPPD)?", "alternativas": ["Gota: joelho e punho, com tofos; CPPD: primeira metatarsofalângica", "Gota: 1ª metatarsofalângica, com tofos; CPPD: joelho ou punho", "Gota: coluna cervical, com rigidez; CPPD: quadril e sacroilíaca", "Ambas acometem apenas o ombro, distinguindo-se pela idade", "Gota: cristais de pirofosfato; CPPD: cristais de urato"], "gabarito": "B", "justificativa": "Gota é urato monossódico, com podagra e tofos; CPPD é pirofosfato, com joelho ou punho e condrocalcinose.", "epônimo": null, "tecnica": "Gota x CPPD", "slide": 13}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Na evolução natural da gota, qual é a fase em que surgem tofos e dano estrutural?", "alternativas": ["Fase 1, com início abrupto, explosivo e dor intensa", "Fase 2, com crise autolimitada de dias a semanas e edema", "Fase 4, com deposição crônica de cristais, tofos e dano", "Fase 3, com recorrência em intervalos menores", "Fase de intervalo, assintomática e sem alteração articular"], "gabarito": "C", "justificativa": "A fase 4 é a deposição crônica, com tofos e dano estrutural; a uricemia isolada não confirma o diagnóstico.", "epônimo": null, "tecnica": "Gota", "slide": 11}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Hemartrose sem trauma claro em paciente anticoagulado. Qual é a conduta diagnóstica correta?", "alternativas": ["Repouso e analgesia, por provável contusão leve e sem exame", "Alta com retorno programado em três meses e orientação", "Infiltração de corticoide sem punção prévia e sem exame", "Exclusão de lesão estrutural grave e análise sinovial", "Apenas ultrassonografia, sem análise do líquido"], "gabarito": "D", "justificativa": "Hemartrose exige exclusão de lesão estrutural grave e análise do líquido; cristais não excluem infecção.", "epônimo": null, "tecnica": "Hemartrose", "slide": 14}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Monoartrite inflamatória que persiste por mais de seis semanas. Como deve ser classificada e conduzida?", "alternativas": ["Aguda resolvida, com alta e retorno apenas se recidivar", "Artrite reativa tardia, sem necessidade de líquido", "Poliartrite recente, com encaminhamento automático", "Osteoartrite confirmada, sem novos exames de rotina", "Monoartrite persistente, com reavaliação das causas"], "gabarito": "E", "justificativa": "Monoartrite com mais de seis semanas é persistente: confirmar inflamação, rever exposições e reavaliar o algoritmo.", "epônimo": null, "tecnica": "Persistente", "slide": 15}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Artrite reumatoide com padrão aditivo e simétrico. Qual é a conduta diante de sinovite clínica evidente?", "alternativas": ["Encaminhamento rápido, sem esperar deformidades", "Aguardar deformidades visíveis para encaminhar", "Observação por seis meses com novo exame de imagem", "Infiltração de corticoide em todas as articulações", "Repouso articular e alta com retorno anual"], "gabarito": "A", "justificativa": "Encaminhar sem esperar deformidades; a sorologia negativa não adia a avaliação diante de sinovite evidente.", "epônimo": null, "tecnica": "AR", "slide": 19}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Paciente com dactilite difusa ('dedo em salsicha'), depressões cupuliformes nas unhas e onicólise. Qual diagnóstico é mais sugerido?", "alternativas": ["Artrite reumatoide soronegativa, com nódulos subcutâneos", "Artrite psoriásica, pelas pistas distais e ungueais", "Gota tofácea, com tofos nos dedos e nas orelhas", "Osteoartrite de mãos, com nódulos de Heberden", "Lúpus eritematoso, com fotossensibilidade e úlceras orais"], "gabarito": "B", "justificativa": "Dactilite, depressões cupuliformes e onicólise são pistas ungueais e distais de artrite psoriásica.", "epônimo": null, "tecnica": "Psoríase", "slide": 20}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Entesite e dactilite em oligoartrite assimétrica de membros inferiores. Qual grupo diagnóstico é sugerido?", "alternativas": ["Artrite reumatoide, com início insidioso e simétrico", "Osteoartrite de joelhos, sem componente inflamatório", "Espondiloartrites, por entesite e dactilite", "Gota, com acometimento de pequenas articulações", "Artrite séptica, com acometimento poliarticular agudo"], "gabarito": "C", "justificativa": "Entesite e dactilite são altamente sugestivas de espondiloartrite, no contexto de oligoartrite de membros inferiores.", "epônimo": null, "tecnica": "Espondiloartrite", "slide": 16}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Fenômeno de Raynaud associado a sintomas secos e artrite. Qual condição sistêmica deve ser pesquisada?", "alternativas": ["Hemocromatose, pela artropatia de segunda metacarpofalângica", "Doença de Paget óssea, pela dor em pelve e membros", "Síndrome de Guillain-Barré, pela fraqueza ascendente", "Síndrome de Sjögren, pela xeroftalmia e xerostomia", "Doença de Dupuytren, pelo nódulo palmar com retração"], "gabarito": "D", "justificativa": "Raynaud, xeroftalmia e xerostomia, com artrite, integram o quadro de doença do tecido conjuntivo, como Sjögren.", "epônimo": null, "tecnica": "Sjögren", "slide": 21}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Artrite que surge semanas após diarreia ou uretrite, com predomínio em membros inferiores. Qual é o diagnóstico?", "alternativas": ["Artrite séptica direta, com início agudo e febre alta", "Gota, com crise na primeira metatarsofalângica", "Artrite viral simultânea, com exantema e timing atual", "Osteoartrite degenerativa, com início progressivo e lento", "Artrite reativa, pós-infecciosa, em membros inferiores"], "gabarito": "E", "justificativa": "Artrite reativa é pós-infecciosa, de semanas, com preferência por membros inferiores; a séptica tem timing atual.", "epônimo": null, "tecnica": "Contexto infeccioso", "slide": 22}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Nódulos ósseos de interfalângicas distais e proximais, sem calor local. Como são chamados e de que processo são característicos?", "alternativas": ["Nódulos de Heberden e de Bouchard, da osteoartrite", "Nódulos de Osler e de Janeway, da endocardite", "Nódulos de Aschoff e de Anitschkow, da febre reumática", "Nódulos de Bouchard e de Lorain, da neurofibromatose", "Nódulos de Dupuytren e de Ledderhose, da fibromatose"], "gabarito": "A", "justificativa": "Heberden acomete a interfalângica distal e Bouchard a proximal; ambos são nódulos ósseos da osteoartrite.", "epônimo": null, "tecnica": "Heberden", "slide": 26}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Aumento de volume articular de consistência dura, indolor à palpação leve, sem calor irradiado. Qual é a hipótese mais provável?", "alternativas": ["Sinovite elástica com derrame, calor local e dor à interlinha", "Aumento ósseo por osteoartrite, de consistência dura", "Bursite pré-patelar com edema subcutâneo e calor", "Tofo gotoso com secreção purulenta e calor local", "Cisto de Baker com flutuação, calor intenso e dor"], "gabarito": "B", "justificativa": "Aumento ósseo endurecido e indolor sugere osteoartrite; sinovite é elástica, dolorosa à interlinha e quente.", "epônimo": null, "tecnica": "Heberden", "slide": 27}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Dor no joelho que piora na marcha, com limitação da rotação interna do quadril. Qual é a conduta de exame correta?", "alternativas": ["Examinar apenas o joelho, pela queixa principal", "Infiltrar o joelho e encaminhar para cirurgia", "Examinar o quadril, pela dor referida ao joelho", "Solicitar eletroneuromiografia de membro inferior", "Repouso absoluto do joelho por quatro semanas"], "gabarito": "C", "justificativa": "Patologias do quadril referem dor no joelho; examine sempre a articulação proximal à queixa.", "epônimo": null, "tecnica": "Quadril", "slide": 28}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Na diferenciação cinética, qual achado sugere lesão periarticular (tendão ou bursa) e não articular?", "alternativas": ["Dor difusa à palpação da interlinha articular bilateral", "Derrame intra-articular global, com contorno articular perdido", "Movimento passivo doloroso, com limitação global ampla", "Dor focal ao palpar o tendão, com resistência dolorosa", "Crepitação difusa com limitação de amplitude passiva"], "gabarito": "D", "justificativa": "Dor focal no tendão ou bursa, com resistência dolorosa, sugere lesão periarticular; a articular dói à interlinha.", "epônimo": null, "tecnica": "Periarticular", "slide": 30}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Olho vermelho doloroso e fotofobia em paciente com artrite de quadro recente. Qual é a conduta correta?", "alternativas": ["Colírio lubrificante e reavaliação em duas semanas", "Observação ambulatorial, pois a dor articular explica tudo", "Antibiótico tópico por sete dias, sem avaliação", "Corticoide oral e alta, sem encaminhamento especializado", "Oftalmologia no mesmo dia, pelo risco de uveíte anterior"], "gabarito": "E", "justificativa": "Olho vermelho doloroso com artrite sugere uveíte anterior, que exige oftalmologia no mesmo dia.", "epônimo": null, "tecnica": "Uveíte", "slide": 36}], "casos_extremos": [{"titulo": "Caso Z1 · Monoartrite com cristais e infecção sobreposta", "texto": "Homem de 63 anos, com gota tofácea conhecida e uso irregular de alopurinol, apresenta monoartrite aguda de joelho esquerdo há 18 horas, com derrame, calor intenso e impossibilidade de apoio. Febre de 38,1 °C. Leucometria 13.000/mm³. Líquido sinovial: 52.000 leucócitos/mm³, cristais de urato monossódico negativamente birrefringentes e Gram negativo.", "perguntas": [{"pergunta": "Qual é a interpretação mais adequada dos achados do líquido e do quadro?", "alternativas": ["Gota isolada, pois os cristais confirmam e dispensam cultura sinovial", "Osteoartrite com derrame, por inflamação local e ausência de cristais", "Artrite séptica isolada, pois a gota não ocorre com febre alta", "Gota com possível infecção sobreposta, pois cristais não excluem", "Pseudogota, pela presença de calor e derrame articular intenso"], "gabarito": "D", "justificativa": "Cristais de urato não excluem infecção; a coexistência é possível e exige cultura e manejo imediato."}, {"pergunta": "Qual é a conduta mais adequada na sequência?", "alternativas": ["Iniciar colchicina e aguardar cultura por sete dias de observação", "Coletar cultura, iniciar antibiótico empírico e reavaliar logo", "Infiltrar corticoide intra-articular antes da coleta de cultura", "Suspender o alopurinol e observar a evolução do quadro articular", "Analgesia com AINE e alta com retorno em uma semana, sem punção"], "gabarito": "B", "justificativa": "Coleta de cultura antes do antibiótico empírico, com manejo articular e reavaliação, é o que a sobreposição exige."}]}, {"titulo": "Caso Z2 · Oligoartrite com dactilite e uveíte", "texto": "Homem de 29 anos, com dor lombar de ritmo inflamatório há 3 anos, apresenta oligoartrite de tornozelo direito e joelho direito, dactilite do 2º pododáctilo, dor no calcanhar à palpação da inserção do tendão de Aquiles, e episódio de olho vermelho doloroso com fotofobia há 2 meses.", "perguntas": [{"pergunta": "Qual grupo diagnóstico e quais pistas extra-articulares são mais relevantes?", "alternativas": ["Espondiloartrite, com entesite, dactilite e uveíte anterior", "Artrite reumatoide, com nódulos e fator reumatoide positivo", "Gota, com tofos e hiperuricemia persistente no tempo", "Osteoartrite de joelho, com osteófitos e rigidez breve", "Artrite reativa tardia, sem relação com a lombalgia"], "gabarito": "A", "justificativa": "Dactilite, entesite, lombalgia inflamatória e uveíte anterior configuram espondiloartrite."}, {"pergunta": "Qual é a conduta de encaminhamento mais adequada para o olho vermelho doloroso?", "alternativas": ["Colírio lubrificante e reavaliação em duas semanas", "Corticoide oral e alta, sem encaminhamento especializado", "Antibiótico tópico por sete dias, sem avaliação prévia", "Oftalmologia no mesmo dia, pelo risco de uveíte anterior", "Observação ambulatorial, pois a dor articular explica os sintomas"], "gabarito": "D", "justificativa": "Olho vermelho doloroso com fotofobia em espondiloartrite sugere uveíte anterior, que exige avaliação oftalmológica no mesmo dia."}]}, {"titulo": "Caso Z3 · Joelho com dor referida do quadril", "texto": "Mulher de 67 anos queixa-se de dor e crepitação no joelho direito, pior ao subir escadas, com derrame de pequeno volume. O joelho tem amplitude preservada, mas há limitação da rotação interna do quadril direito com dor inguinal reproduzida à manobra de FABER. A marcha tem leve claudicação.", "perguntas": [{"pergunta": "Qual é a interpretação do quadro?", "alternativas": ["Osteoartrite isolada do joelho, pela crepitação e pelo derrame", "Lesão meniscal isolada, pela dor ao subir escadas e pelo derrame", "Dor referida por doença do quadril, com exame proximal indicado", "Bursite pré-patelar, pelo derrame e pelo aumento de volume", "Neuropatia periférica, pela claudicação e pela dor ao caminhar"], "gabarito": "C", "justificativa": "Dor no joelho com limitação de rotação interna e dor inguinal ao FABER sugere dor referida do quadril; examine sempre a articulação proximal."}, {"pergunta": "Qual padrão de limitação mais favorece a origem articular do quadril?", "alternativas": ["Limitação da rotação interna e abdução, com dor inguinal", "Limitação apenas na flexão, com rotação interna livre", "Limitação somente da extensão, sem nenhuma dor associada", "Limitação da rotação externa, com dor na região posterior", "Limitação apenas da adução, com dor na região trocantérica"], "gabarito": "A", "justificativa": "Limitação de rotação interna e abdução com dor inguinal é o padrão típico de comprometimento articular do quadril."}]}]};
